`timescale 1ns / 1ps
// ------------------------------------------------------------------------------
// test_RV_ldst: self-checking Wrapper-level test for lb/lh/lbu/lhu/sb/sh
// (with lw/sw regression, load to x0, sb to an MMIO register, misaligned sh/lh).
//
// Generated by gen_ldst_tb.py. Expected values come from an ISA reference model.
// The program is loaded into dut.IROM / dut.DMEM by this testbench, overriding
// AA_IROM.mem / AA_DMEM.mem for this simulation only (the .mem files are untouched).
// No hazard unit is assumed: every register result is consumed >= 4 instructions later.
// ------------------------------------------------------------------------------
module test_RV_ldst;

    reg         CLK = 1'b0;
    reg         RESET = 1'b1;
    reg  [15:0] DIP = 16'd0;
    reg  [2:0]  PB = 3'd0;
    wire [7:0]  LED_OUT;
    wire [6:0]  LED_PC;
    wire [31:0] SEVENSEGHEX;
    wire [7:0]  UART_TX;
    reg         UART_TX_ready = 1'b1;
    wire        UART_TX_valid;
    reg  [7:0]  UART_RX = 8'd0;
    reg         UART_RX_valid = 1'b0;
    wire        UART_RX_ack;
    wire        OLED_Write;
    wire [6:0]  OLED_Col;
    wire [5:0]  OLED_Row;
    wire [23:0] OLED_Data;
    reg  [31:0] ACCEL_Data = 32'd0;
    reg         ACCEL_DReady = 1'b0;

    Wrapper dut (
        .DIP(DIP), .PB(PB), .LED_OUT(LED_OUT), .LED_PC(LED_PC), .SEVENSEGHEX(SEVENSEGHEX),
        .UART_TX(UART_TX), .UART_TX_ready(UART_TX_ready), .UART_TX_valid(UART_TX_valid),
        .UART_RX(UART_RX), .UART_RX_valid(UART_RX_valid), .UART_RX_ack(UART_RX_ack),
        .OLED_Write(OLED_Write), .OLED_Col(OLED_Col), .OLED_Row(OLED_Row), .OLED_Data(OLED_Data),
        .ACCEL_Data(ACCEL_Data), .ACCEL_DReady(ACCEL_DReady),
        .RESET(RESET), .CLK(CLK)
    );

    always #5 CLK = ~CLK;

    integer i;
    integer pass_count = 0;
    integer fail_count = 0;

    task check;
        input [8*24-1:0] name;
        input [31:0] got;
        input [31:0] exp;
        begin
            if (got === exp) begin
                pass_count = pass_count + 1;
                $display("PASS  %0s = 0x%08h", name, got);
            end else begin
                fail_count = fail_count + 1;
                $display("FAIL  %0s = 0x%08h, expected 0x%08h", name, got, exp);
            end
        end
    endtask

    initial begin
        // Wait for the Wrapper's $readmemh at time 0, then load this test's program and data
        #1;
        for (i = 0; i < 128; i = i + 1) dut.IROM[i] = 32'h00000013;   // fill with nop
        dut.IROM[ 0] = 32'h100100B7;   // 0x00400000: lui  x1, 0x10010
        dut.IROM[ 1] = 32'hFFFF02B7;   // 0x00400004: lui  x5, 0xffff0
        dut.IROM[ 2] = 32'h00000013;   // 0x00400008: nop
        dut.IROM[ 3] = 32'h00000013;   // 0x0040000C: nop
        dut.IROM[ 4] = 32'h00000013;   // 0x00400010: nop
        dut.IROM[ 5] = 32'h0080A503;   // 0x00400014: lw   x10, 8(x1)
        dut.IROM[ 6] = 32'h00000013;   // 0x00400018: nop
        dut.IROM[ 7] = 32'h00000013;   // 0x0040001C: nop
        dut.IROM[ 8] = 32'h00000013;   // 0x00400020: nop
        dut.IROM[ 9] = 32'h00008583;   // 0x00400024: lb   x11, 0(x1)
        dut.IROM[10] = 32'h00108603;   // 0x00400028: lb   x12, 1(x1)
        dut.IROM[11] = 32'h00208683;   // 0x0040002C: lb   x13, 2(x1)
        dut.IROM[12] = 32'h00308703;   // 0x00400030: lb   x14, 3(x1)
        dut.IROM[13] = 32'h0000C783;   // 0x00400034: lbu  x15, 0(x1)
        dut.IROM[14] = 32'h0010C803;   // 0x00400038: lbu  x16, 1(x1)
        dut.IROM[15] = 32'h0020C883;   // 0x0040003C: lbu  x17, 2(x1)
        dut.IROM[16] = 32'h0030C903;   // 0x00400040: lbu  x18, 3(x1)
        dut.IROM[17] = 32'h00009983;   // 0x00400044: lh   x19, 0(x1)
        dut.IROM[18] = 32'h00209A03;   // 0x00400048: lh   x20, 2(x1)
        dut.IROM[19] = 32'h0000DA83;   // 0x0040004C: lhu  x21, 0(x1)
        dut.IROM[20] = 32'h0020DB03;   // 0x00400050: lhu  x22, 2(x1)
        dut.IROM[21] = 32'h00408B83;   // 0x00400054: lb   x23, 4(x1)
        dut.IROM[22] = 32'h00708C03;   // 0x00400058: lb   x24, 7(x1)
        dut.IROM[23] = 32'h00609C83;   // 0x0040005C: lh   x25, 6(x1)
        dut.IROM[24] = 32'h00409D03;   // 0x00400060: lh   x26, 4(x1)
        dut.IROM[25] = 32'h0040AD83;   // 0x00400064: lw   x27, 4(x1)
        dut.IROM[26] = 32'h00A08623;   // 0x00400068: sb   x10, 12(x1)
        dut.IROM[27] = 32'h00A088A3;   // 0x0040006C: sb   x10, 17(x1)
        dut.IROM[28] = 32'h00A08B23;   // 0x00400070: sb   x10, 22(x1)
        dut.IROM[29] = 32'h00A08DA3;   // 0x00400074: sb   x10, 27(x1)
        dut.IROM[30] = 32'h00A09E23;   // 0x00400078: sh   x10, 28(x1)
        dut.IROM[31] = 32'h02A09123;   // 0x0040007C: sh   x10, 34(x1)
        dut.IROM[32] = 32'h02A0A223;   // 0x00400080: sw   x10, 36(x1)
        dut.IROM[33] = 32'h0110CE03;   // 0x00400084: lbu  x28, 17(x1)
        dut.IROM[34] = 32'h0140AE83;   // 0x00400088: lw   x29, 20(x1)
        dut.IROM[35] = 32'h0220DF03;   // 0x0040008C: lhu  x30, 34(x1)
        dut.IROM[36] = 32'h00008003;   // 0x00400090: lb   x0, 0(x1)
        dut.IROM[37] = 32'h06A28023;   // 0x00400094: sb   x10, 96(x5)
        dut.IROM[38] = 32'h02A094A3;   // 0x00400098: sh   x10, 41(x1)
        dut.IROM[39] = 32'h02909F83;   // 0x0040009C: lh   x31, 41(x1)
        dut.IROM[40] = 32'h0000006F;   // 0x004000A0: jal  x0, 0
        dut.IROM[41] = 32'h00000013;   // 0x004000A4: nop
        dut.IROM[42] = 32'h00000013;   // 0x004000A8: nop
        dut.IROM[43] = 32'h00000013;   // 0x004000AC: nop

        dut.DMEM[ 0] = 32'h8899AABB;
        dut.DMEM[ 1] = 32'h12345678;
        dut.DMEM[ 2] = 32'hCAFEBABE;
        dut.DMEM[ 3] = 32'h11111111;
        dut.DMEM[ 4] = 32'h11111111;
        dut.DMEM[ 5] = 32'h11111111;
        dut.DMEM[ 6] = 32'h11111111;
        dut.DMEM[ 7] = 32'h11111111;
        dut.DMEM[ 8] = 32'h11111111;
        dut.DMEM[ 9] = 32'h11111111;
        dut.DMEM[10] = 32'h11111111;

        #20 RESET = 1'b0;
        repeat (64) @(posedge CLK);
        #1;

        $display("");
        $display("==== test_RV_ldst: registers ====");
        check("x0 (lb x0)", (dut.RV1.RegFile1.RegBank[0] === 32'hx) ? 32'h0 : dut.RV1.RegFile1.RegBank[0], 32'h00000000);
        check("x10", dut.RV1.RegFile1.RegBank[10], 32'hCAFEBABE);
        check("x11", dut.RV1.RegFile1.RegBank[11], 32'hFFFFFFBB);
        check("x12", dut.RV1.RegFile1.RegBank[12], 32'hFFFFFFAA);
        check("x13", dut.RV1.RegFile1.RegBank[13], 32'hFFFFFF99);
        check("x14", dut.RV1.RegFile1.RegBank[14], 32'hFFFFFF88);
        check("x15", dut.RV1.RegFile1.RegBank[15], 32'h000000BB);
        check("x16", dut.RV1.RegFile1.RegBank[16], 32'h000000AA);
        check("x17", dut.RV1.RegFile1.RegBank[17], 32'h00000099);
        check("x18", dut.RV1.RegFile1.RegBank[18], 32'h00000088);
        check("x19", dut.RV1.RegFile1.RegBank[19], 32'hFFFFAABB);
        check("x20", dut.RV1.RegFile1.RegBank[20], 32'hFFFF8899);
        check("x21", dut.RV1.RegFile1.RegBank[21], 32'h0000AABB);
        check("x22", dut.RV1.RegFile1.RegBank[22], 32'h00008899);
        check("x23", dut.RV1.RegFile1.RegBank[23], 32'h00000078);
        check("x24", dut.RV1.RegFile1.RegBank[24], 32'h00000012);
        check("x25", dut.RV1.RegFile1.RegBank[25], 32'h00001234);
        check("x26", dut.RV1.RegFile1.RegBank[26], 32'h00005678);
        check("x27", dut.RV1.RegFile1.RegBank[27], 32'h12345678);
        check("x28", dut.RV1.RegFile1.RegBank[28], 32'h000000BE);
        check("x29", dut.RV1.RegFile1.RegBank[29], 32'h11BE1111);
        check("x30", dut.RV1.RegFile1.RegBank[30], 32'h0000BABE);
        check("x31", dut.RV1.RegFile1.RegBank[31], 32'hFFFFBABE);

        $display("==== test_RV_ldst: DMEM ====");
        check("DMEM[0]", dut.DMEM[0], 32'h8899AABB);
        check("DMEM[1]", dut.DMEM[1], 32'h12345678);
        check("DMEM[2]", dut.DMEM[2], 32'hCAFEBABE);
        check("DMEM[3]", dut.DMEM[3], 32'h111111BE);
        check("DMEM[4]", dut.DMEM[4], 32'h1111BE11);
        check("DMEM[5]", dut.DMEM[5], 32'h11BE1111);
        check("DMEM[6]", dut.DMEM[6], 32'hBE111111);
        check("DMEM[7]", dut.DMEM[7], 32'h1111BABE);
        check("DMEM[8]", dut.DMEM[8], 32'hBABE1111);
        check("DMEM[9]", dut.DMEM[9], 32'hCAFEBABE);
        check("DMEM[10]", dut.DMEM[10], 32'h1111BABE);

        $display("==== test_RV_ldst: MMIO ====");
        check("LED_OUT (sb)", {24'd0, LED_OUT}, 32'h000000BE);

        $display("");
        $display("==== %0d passed, %0d failed ====", pass_count, fail_count);
        $finish;
    end

endmodule
